import React, { useEffect, useState, useMemo } from "react";
import {
  Box,
  Typography,
  Grid,
  Card,
  Button,
  CircularProgress,
  useTheme,
  useMediaQuery,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Badge,
} from "@mui/material";
import { ShoppingCart } from "@mui/icons-material";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useLocation } from "react-router-dom";
import { getProductsByConnection } from "../redux/slices/sellerProductSlice";
import { addToCart, getCart } from "../redux/slices/cartSlice";
import { useSuccessSnackbar } from "../Buyer/useSuccessSnackbar";

const placeholderStyle = {
  width: "100%",
  paddingTop: "66.66%",
  background: "#ededed",
  position: "relative",
  borderRadius: 1,
};

export default function ViewProducts() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const location = useLocation();
  const { connectionId, otherUserId } = location.state || {};

  const { allProducts, loading, error } = useSelector((state) => state.products);
  const { cart, loading: cartLoading } = useSelector((state) => state.cart);
  const userId = useSelector((state) => state.user?.user?._id);

  const [showSuccess, snackElem] = useSuccessSnackbar();
  const [openModal, setOpenModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [animateCart, setAnimateCart] = useState(false);

  // ✅ Fetch products for this connection
  useEffect(() => {
    if (connectionId && otherUserId) {
      dispatch(getProductsByConnection({ connectionId, otherUserId }));
    }
  }, [dispatch, connectionId, otherUserId]);

  // ✅ Fetch cart for all sellers (once products load)
  useEffect(() => {
    if (userId && allProducts?.length) {
      const uniqueSellerIds = [
        ...new Set(allProducts.map((p) => p?.user?._id).filter(Boolean)),
      ];

      uniqueSellerIds.forEach((sellerId) => {
        dispatch(getCart({ userId, seller: sellerId }));
      });
    }
  }, [dispatch, userId, allProducts]);

  // ✅ Calculate total cart count (supports multi-seller carts)
  const totalCartCount = useMemo(() => {
    if (!cart) return 0;
    if (Array.isArray(cart)) {
      return cart.reduce((sum, singleCart) => sum + (singleCart?.items?.length || 0), 0);
    }
    return cart?.items?.length || 0;
  }, [cart]);

 // ✅ Add product to cart and refresh only that seller’s cart
const handleAdd = async (product) => {
  if (!userId) return showSuccess("Please log in to add items to cart");

  try {
    // Bounce animation
    setAnimateCart(true);
    setTimeout(() => setAnimateCart(false), 300);

    await dispatch(
      addToCart({
        userId,
        productId: product._id,
        quantity: 1,
      })
    ).unwrap();

    showSuccess("Added to cart successfully!");

    // ✅ Refresh cart ONLY for that seller (not all)
    if (product?.user?._id) {
      await dispatch(getCart({ userId, seller: product.user._id }));
    }
  } catch (err) {
    showSuccess(err?.message || "Failed to add to cart");
  }
};


  const handleUserClick = (user) => {
    setSelectedUser(user);
    setOpenModal(true);
  };

  const handleCloseModal = () => {
    setOpenModal(false);
    setSelectedUser(null);
  };

  // ✅ Loading / Error / Empty States
  if (loading) {
    return (
      <Box
        sx={{
          width: "100%",
          height: "80vh",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <CircularProgress size={50} />
      </Box>
    );
  }

  if (error) {
    return (
      <Typography color="error" align="center" sx={{ mt: 5 }}>
        {error}
      </Typography>
    );
  }

  if (!allProducts?.length) {
    return (
      <Typography align="center" sx={{ mt: 5 }}>
        No visible products found for this connection.
      </Typography>
    );
  }

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        background: "#f8fafc",
        px: { xs: 2, sm: 4, md: 7, lg: 12 },
        py: { xs: 2, sm: 4, md: 5 },
        boxSizing: "border-box",
        display: "flex",
        justifyContent: "center",
      }}
    >
      <Box sx={{ width: "100%", maxWidth: 1400, mx: "auto" }}>
        {/* ✅ Heading + Cart beside it */}
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: isMobile ? "center" : "space-between",
            flexWrap: "wrap",
            gap: 2,
            mb: 1,
          }}
        >
          <Typography
            fontWeight={700}
            fontSize={{ xs: 22, md: 28 }}
            color="#22364a"
          >
            View Products
          </Typography>

          {/* 🛒 Cart beside heading */}
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 1,
              cursor: "pointer",
              animation: animateCart ? "pulse 0.3s ease" : "none",
              "@keyframes pulse": {
                "0%": { transform: "scale(1)" },
                "50%": { transform: "scale(1.15)" },
                "100%": { transform: "scale(1)" },
              },
            }}
            onClick={() => {
              const uniqueSellerIds = [
                ...new Set(allProducts.map((p) => p?.user?._id).filter(Boolean)),
              ];
              const uniqueBuyerCategories = [
                ...new Set(
                  allProducts
                    .flatMap((p) => p?.productVisibility || [])
                    .map((v) => v?.buyerCategory)
                    .filter(Boolean)
                ),
              ];
              navigate("/buyer-dashboard/cart", {
                state: { sellerIds: uniqueSellerIds, buyerCategories: uniqueBuyerCategories },
              });
            }}
          >
            <ShoppingCart
              sx={{ color: "#22364a", fontSize: { xs: 25, md: 28 } }}
            />
            <Typography
              fontWeight={700}
              fontSize={{ xs: 18, md: 20 }}
              color="#22364a"
            >
              Cart ({totalCartCount})
            </Typography>
          </Box>
        </Box>

        {/* ✅ Existing small cart icon (kept same) */}
        {/* <Badge badgeContent={totalCartCount} color="primary" sx={{ mr: 1.5, mt: 2 }}>
          <IconButton
            size="large"
            aria-label="show cart items"
            color="inherit"
            sx={{ mt: -2 }}
            onClick={() => {
              const uniqueSellerIds = [
                ...new Set(allProducts.map((p) => p?.user?._id).filter(Boolean)),
              ];
              const uniqueBuyerCategories = [
                ...new Set(
                  allProducts
                    .flatMap((p) => p?.productVisibility || [])
                    .map((v) => v?.buyerCategory)
                    .filter(Boolean)
                ),
              ];
              navigate("/buyer-dashboard/cart", {
                state: { sellerIds: uniqueSellerIds, buyerCategories: uniqueBuyerCategories },
              });
            }}
          >
            <ShoppingCart />
          </IconButton>
        </Badge> */}

        {/* ✅ Product Grid */}
        <Grid container spacing={isMobile ? 2 : 4} sx={{ mt: 1 }}>
          {allProducts.map((product) => (
            <Grid item xs={12} sm={6} md={4} key={product._id}>
              <Card
                sx={{
                  p: 3,
                  borderRadius: 3,
                  background: "#fff",
                  boxShadow: "0 1px 6px rgba(0,0,0,0.1)",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "flex-start",
                  gap: 1.5,
                  height: "100%",
                }}
              >
                <Box sx={placeholderStyle}>
                  <img
                    src={
                      product.image ||
                      "https://via.placeholder.com/300x200?text=No+Image"
                    }
                    alt={product.name}
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      width: "100%",
                      height: "100%",
                      objectFit: "cover",
                      borderRadius: 8,
                    }}
                  />
                </Box>

                <Typography fontWeight={700} fontSize={16} color="#22364a">
                  {product.name}
                </Typography>

                <Typography
                  fontSize={14}
                  color="#2961e1"
                  sx={{
                    cursor: "pointer",
                    textDecoration: "underline",
                    mb: 0.7,
                  }}
                  onClick={() => handleUserClick(product.user)}
                >
                  Sold by {product.user?.name || "Unknown Seller"}
                </Typography>

                <Typography
                  fontWeight={700}
                  fontSize={16}
                  color="#059b37"
                  sx={{ mb: 2 }}
                >
                  ₹{product.price?.toFixed(2)}
                </Typography>

                <Button
                  variant="contained"
                  fullWidth
                  disabled={cartLoading}
                  sx={{
                    background: "#2961e1",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 17,
                    borderRadius: 2,
                    py: 1.1,
                    textTransform: "none",
                    "&:hover": { background: "#1146aa" },
                    mt: "auto",
                  }}
                  onClick={() => handleAdd(product)}
                >
                  {cartLoading ? "Adding..." : "Add to Cart"}
                </Button>
              </Card>
            </Grid>
          ))}
        </Grid>

        {/* ✅ Seller Info Modal */}
        <Dialog open={openModal} onClose={handleCloseModal}>
          <DialogTitle>Seller Details</DialogTitle>
          <DialogContent>
            {selectedUser ? (
              <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
                <Typography>
                  <strong>Name:</strong> {selectedUser.name}
                </Typography>
                <Typography>
                  <strong>Email:</strong> {selectedUser.email}
                </Typography>
                <Typography>
                  <strong>Phone:</strong> {selectedUser.phone}
                </Typography>
                <Typography>
                  <strong>Business Name:</strong> {selectedUser.businessName}
                </Typography>
                <Typography>
                  <strong>Business Address:</strong>{" "}
                  {selectedUser.businessAddress}
                </Typography>
              </Box>
            ) : (
              <Typography>No seller info available</Typography>
            )}
          </DialogContent>
          <DialogActions>
            <Button onClick={handleCloseModal} variant="contained">
              Close
            </Button>
          </DialogActions>
        </Dialog>

        {snackElem}
      </Box>
    </Box>
  );
}